function setView(v){if(v==='gen'&&S.later){S.later=false;gen();}document.querySelector('header h1').textContent=v==='home'?'Trainersapp':v==='sen'?'Trainingsgenerator Jeugd & Senioren':v==='aanval'?'Aanval: codes en combinaties':'Trainingsgenerator Mini’s';['home','gen','sen','rot','def','aanval'].forEach(k=>{$('v_'+k).style.display=k===v?'':'none';$('t_'+k).className=k===v?'on':'';});if(v==='sen')senView();if(v==='rot')rotView();if(v==='def')defView();if(window.aanvalView)aanvalView(v==='aanval');}
function rotView(){
 $('rotBtns').innerHTML=[1,2,3,4,5,6].map(r=>'<button class="'+(r===rotN?'on':'')+'" onclick="rotN='+r+';rotF=0;rotView()">Rotatie '+r+' (SV pos '+[1,6,5,4,3,2][r-1]+')</button>').join('');
 const R=ROT[rotN];
 $('rotTitle').textContent=R.title;$('rotSummary').textContent=R.summary+' Na een gescoord punt (fase 4) draait het team door: '+rotSrv(rotN)+' staat dan op Pos 2, loopt naar Pos 1 en serveert. Scoort het team op eigen service, dan serveert dezelfde speler gewoon opnieuw.';
 $('rotRoles').innerHTML=Object.entries(R.players).map(([k,o])=>'<div class="rl"><span class="tag" style="background:'+o.c+'">'+k+'</span><span>'+esc(o.role)+'</span></div>').join('');
 rotDraw();
}
// staat de 3D-weergave over de 2D-tekening heen, dan hoeft de (verborgen) 2D-tekening niet elk beeldje opnieuw: dat maakt 3D vloeiender
function skip2d(id){const e=$(id),w=e&&e.parentNode;return !!(w&&w.classList&&w.classList.contains('a3on')&&e.firstChild);}
function rotDraw(){
 const R=ROT[rotN],seg=Math.min(3,Math.floor(rotF)),lt=rotF-seg,st=ease(lt);
 $('rotPhase').textContent=['Fase 1: Service onderweg: SV, MID1 en DIA maken direct ruimte','Fase 2: Pass naar SV: alle 4 de aanvallers halen uit om aan te lopen','Fase 3: 4 set-up opties vanuit SV: iedereen loopt tegelijk aan!',rotCap4(rotN)][seg];
 const sl=$('rotSlider');if(document.activeElement!==sl)sl.value=rotF.toFixed(2);
 if(skip2d('rotSvg'))return;
 let ps='';
 Object.entries(R.players).forEach(([k,o])=>{
  if(seg===3){
   const q=rotP4(rotN,k,lt),px=q[0],py=mapY(q[1]),pos=rotPos(rotN)[k],b0=RPOS[pos],c0=RPOS[RNEXT[pos]],isS=k===rotSrv(rotN);
   if(lt>=.3&&lt<.9)ps+='<line x1="'+b0[0]+'" y1="'+mapY(b0[1])+'" x2="'+c0[0]+'" y2="'+mapY(c0[1])+'" stroke="'+o.c+'" stroke-width="2.4" stroke-dasharray="5,4" opacity=".7"/>';
   ps+=S2D.tok(px,py,k,o.c,16,{fs:10.5});
   if(isS&&lt>=.4)ps+='<circle cx="'+px+'" cy="'+py+'" r="22" fill="none" stroke="#fff" stroke-width="3" stroke-dasharray="4 3"/>'+S2D.ball(px+21,py-14);
   if(isS&&lt>=.85)ps+='<rect x="'+(px-36)+'" y="'+(py+25)+'" width="72" height="15" rx="3" fill="#1d1d1b" fill-opacity=".9" stroke="#fde047"/><text x="'+px+'" y="'+(py+36)+'" fill="#fde047" font-size="8.5" font-weight="900" text-anchor="middle">SERVEERT</text>';
   return;}
  const a=o.kf[seg],b=o.kf[seg+1]||a,ax=a[0],ay=mapY(a[1]),bx=b[0],by=mapY(b[1]);
  let x=lerp(ax,bx,st),y=lerp(ay,by,st),g='';
  if(seg===1&&o.via){const cx=o.via[0],cy=mapY(o.via[1]),u=1-st;x=u*u*ax+2*u*st*cx+st*st*bx;y=u*u*ay+2*u*st*cy+st*st*by;g='<path d="M '+ax+' '+ay+' Q '+cx+' '+cy+' '+bx+' '+by+'" fill="none" stroke="'+o.c+'" stroke-width="2.4" stroke-dasharray="5,4" opacity=".75"/>';}
  else
  if(seg===0&&o.arc0){x+=Math.sin(st*Math.PI)*o.arc0;g='<path d="M '+ax+' '+ay+' Q '+((ax+bx)/2+o.arc0*1.35)+' '+((ay+by)/2)+' '+bx+' '+by+'" fill="none" stroke="'+o.c+'" stroke-width="2.4" stroke-dasharray="5,4" opacity=".8"/>';}
  else if(Math.hypot(bx-ax,by-ay)>5)g='<line x1="'+ax+'" y1="'+ay+'" x2="'+bx+'" y2="'+by+'" stroke="'+o.c+'" stroke-width="2.4" stroke-dasharray="5,4" opacity=".75"/>';
  ps+=g+S2D.tok(x,y,k,o.c,16,{fs:10.5});
 });
 const rv=R.players[R.recv].kf[0],pass=[rv[0],mapY(rv[1])],sv=[336,mapY(188)],srv=[280,48];
 let bs='';
 if(seg===3){if(lt<.4)bs='<rect x="150" y="318" width="260" height="20" rx="4" fill="#1d1d1b" fill-opacity=".9" stroke="#fde047"/><text x="280" y="332" fill="#fde047" font-size="10.5" font-weight="900" text-anchor="middle">PUNT GESCOORD!</text>';}
 else if(seg===0)bs='<line x1="'+srv[0]+'" y1="'+srv[1]+'" x2="'+pass[0]+'" y2="'+pass[1]+'" stroke="#fde047" stroke-width="2" stroke-dasharray="5,4" opacity=".75"/>'+S2D.ball(lerp(srv[0],pass[0],lt),lerp(srv[1],pass[1],lt));
 else if(seg===1)bs='<line x1="'+pass[0]+'" y1="'+pass[1]+'" x2="'+sv[0]+'" y2="'+sv[1]+'" stroke="#34d399" stroke-width="2.2" stroke-dasharray="5,4" opacity=".8"/>'+S2D.ball(lerp(pass[0],sv[0],lt),lerp(pass[1],sv[1],lt)-Math.sin(lt*Math.PI)*24);
 else if(seg===2)bs=R.tg.map(t=>{const tx=t.to[0],ty=mapY(t.to[1]);return '<line x1="'+sv[0]+'" y1="'+sv[1]+'" x2="'+tx+'" y2="'+ty+'" stroke="'+t.col+'" stroke-width="2.2" stroke-dasharray="4,3" opacity=".85"/>'+S2D.ball(lerp(sv[0],tx,lt),lerp(sv[1],ty,lt)-Math.sin(lt*Math.PI)*18,8.5)+'<rect x="'+(tx-32)+'" y="'+(ty-30)+'" width="64" height="14" rx="3" fill="#1d1d1b" fill-opacity=".88" stroke="'+t.col+'"/><text x="'+tx+'" y="'+(ty-20)+'" fill="#fff" font-size="7.5" font-weight="900" text-anchor="middle">'+t.label+'</text>';}).join('');
 $('rotSvg').innerHTML='<svg viewBox="0 0 560 680" class="tac" style="max-height:560px" role="img" aria-label="5-1 rotatie '+rotN+'">'+S2D.court560()+ps+bs+'</svg>';
}
function scrubRot(v){rotPlay=false;rotF=parseFloat(v);$('rotPlay').textContent='Afspelen';rotDraw();}
function toggleRot(){rotPlay=!rotPlay;$('rotPlay').textContent=rotPlay?'Pauzeer':'Afspelen';}
function restartRot(){rotF=0;rotPlay=true;$('rotPlay').textContent='Pauzeer';rotDraw();}
$('rotSlider').oninput=e=>scrubRot(e.target.value);
let rotLast=0;
function rotLoop(ts){
 const dt=Math.min(.05,(ts-rotLast)/1000);rotLast=ts;
 if(rotPlay&&$('v_rot').style.display!=='none'){rotF+=dt*.48;if(rotF>=4)rotF=0;rotDraw();}
 requestAnimationFrame(rotLoop);
}
requestAnimationFrame(rotLoop);
